import React from 'react';

const Header = () => {
  return (
    <header style={{
      background: 'var(--neutral-charcoal)',
      color: 'var(--text-white)',
      padding: '12px 40px',
      boxShadow: 'var(--shadow-light)',
      position: 'sticky',
      top: 0,
      zIndex: 100,
    }}>
      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
        <h1 style={{ color: 'var(--accent-gold)', fontSize: '24px', fontWeight: '700', margin: 0, lineHeight: 1 }}>
          Artemis Main
        </h1>
        <nav style={{ display: 'flex', gap: '30px' }}>
          <a href="/" style={{ color: 'var(--text-white)', textDecoration: 'none', fontWeight: '500' }}>Home</a>
        </nav>
      </div>
    </header>
  );
};

export default Header;
